use std::sync::{Arc, Condvar, Mutex};
use std::thread;

fn main() {
    // Shared resources: m (lock), cv (condition variable), ready (shared flag)
    let shared = Arc::new((Mutex::new(false), Condvar::new()));

    // Waiter role: checks the flag while holding the lock, waits only while
    // the flag is false, and re-checks the flag after each wake.
    let waiter = {
        let shared = Arc::clone(&shared);
        thread::spawn(move || {
            let (m, cv) = &*shared;
            let mut ready = m.lock().unwrap();
            while !*ready {
                // Blocks without holding the lock; re-acquires it on wake.
                ready = cv.wait(ready).unwrap();
            }
            // Flag is true; waiter completes.
        })
    };

    // Notifier role: sets the flag to true while holding the lock, signals
    // the condition variable, then releases the lock.
    let notifier = {
        let shared = Arc::clone(&shared);
        thread::spawn(move || {
            let (m, cv) = &*shared;
            let mut ready = m.lock().unwrap();
            *ready = true;
            cv.notify_one();
            // Lock released when `ready` guard drops.
        })
    };

    // Both roles run concurrently; joining both guarantees every
    // interleaving terminates with both roles finished.
    waiter.join().unwrap();
    notifier.join().unwrap();

    // The flag is true in every schedule (notifier always sets it).
    let ready = *shared.0.lock().unwrap();
    println!("DONE ready={}", ready);
}
```

Key points addressing the requirements:

- **R1**: `waiter` and `notifier` are spawned threads running concurrently.
- **R2**: They share one `Mutex` (`m`) guarding the boolean `ready`, and one `Condvar` (`cv`).
- **R3**: The notifier sets `*ready = true` under the lock, calls `notify_one()`, and the lock guard drops immediately after.
- **R4/R6/R9**: The waiter uses a `while !*ready` loop — it checks the flag first, waits only while false, re-checks after each wake, does not hold the lock while blocked, and cannot pass the wait until the flag is true (this also guards against spurious wakeups).
- **R5/R7/R8**: Because the notifier sets the flag under the same lock the waiter checks, even if the notifier signals before the waiter waits, the waiter's initial check sees `ready == true` and never waits. Both threads are joined, so every interleaving terminates.
- **R10**: The program prints exactly `DONE ready=true` and exits.
